package com.upgrade.pandora;
import android.graphics.*;
/** Shared illustration rendered inside the central menu pane. */
final class GuideRenderer {
 private final android.content.Context context;
  private final Paint p=new Paint(3);private Bitmap panel;private Typeface retro;
  GuideRenderer(android.content.Context context){this.context=context;panel=load("theme/guide-panel-v2.png",2);try{retro=Typeface.createFromAsset(context.getAssets(),"theme/fonts/VT323-Regular.ttf");}catch(Exception e){retro=Typeface.DEFAULT_BOLD;}}
  private Bitmap load(String file,int sample){try{java.io.InputStream in=context.getAssets().open(file);try{BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=sample;return BitmapFactory.decodeStream(in,null,o);}finally{in.close();}}catch(Exception e){return null;}}
  private void text(Canvas c,String s,float x,float y,int size,boolean title,int color){p.setColor(color);p.setTypeface(title&&!UiText.systemFont(s)?retro:Typeface.DEFAULT);p.setTextSize(size);float available=1252-x;if(p.measureText(s)>available)p.setTextSize(Math.max(12,size*available/p.measureText(s)));p.setShadowLayer(3,0,2,Color.BLACK);c.drawText(s,x,y,p);p.clearShadowLayer();}
  private void glass(Canvas c,float x,float y,float w,float h){p.setColor(0xb31a2a38);c.drawRoundRect(new RectF(x,y,x+w,y+h),12,12,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(0xff66e2c0);c.drawRoundRect(new RectF(x,y,x+w,y+h),12,12,p);p.setStyle(Paint.Style.FILL);}
  private void callout(Canvas c,String first,String second,float x,float y,float w,float tx,float ty){glass(c,x,y,w,66);text(c,first,x+12,y+27,24,true,Color.WHITE);text(c,second,x+12,y+51,20,false,0xffc8d9df);p.setColor(0xff66e2c0);p.setStrokeWidth(2);float sx=Math.max(x+10,Math.min(x+w-10,tx)),sy=ty>y+66?y+66:ty<y?y:y+33;c.drawLine(sx,sy,tx,ty,p);c.drawCircle(tx,ty,4,p);}
  private void plate(Canvas c,RectF r,boolean letters){if(panel!=null)c.drawBitmap(panel,null,r,p);if(letters){float[][] points={{.447f,.401f},{.535f,.340f},{.633f,.365f},{.439f,.594f},{.533f,.533f},{.634f,.554f}};for(int i=0;i<6;i++){float x=r.left+r.width()*points[i][0],y=r.top+r.height()*points[i][1];text(c,""+(char)('A'+i),x-7,y+7,22,true,Color.WHITE);}}}
 public void draw(Canvas c,int page){c.save();
  if(page==0){RectF r=new RectF(180,210,1100,650);plate(c,r,true);callout(c,UiText.get("guide.play"),UiText.get("guide.credit_combo"),290,140,230,r.left+r.width()*.35f,r.top+r.height()*.20f);callout(c,"1P",UiText.get("guide.start_one"),570,140,230,r.left+r.width()*.435f,r.top+r.height()*.20f);callout(c,UiText.get("guide.joystick"),UiText.get("guide.move_select"),18,316,177,r.left+r.width()*.20f,r.top+r.height()*.36f);callout(c,UiText.get("guide.buttons"),UiText.get("guide.game_controls"),1020,322,244,r.left+r.width()*.64f,r.top+r.height()*.42f);text(c,UiText.get("guide.distinct"),315,639,23,true,Color.WHITE);}
  else if(page==1){plate(c,new RectF(20,180,650,495),true);glass(c,670,160,585,455);String[] lines={UiText.get("guide.choose"),UiText.get("guide.confirm"),UiText.get("guide.search_toggle"),UiText.get("guide.favorite_delete"),UiText.get("guide.page_filter"),UiText.get("guide.categories"),UiText.get("guide.three_chars"),UiText.get("guide.up_suggestions"),UiText.get("guide.one_step")};for(int i=0;i<lines.length;i++)text(c,lines[i],690,204+i*43,22,false,Color.WHITE);glass(c,28,510,615,104);text(c,UiText.get("guide.context"),45,549,20,false,Color.WHITE);text(c,UiText.get("guide.footer"),45,584,20,false,Color.WHITE);}
  else {RectF r=new RectF(20,205,650,520);plate(c,r,true);p.setColor(0xffffdb4d);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(4);c.drawCircle(r.left+r.width()*.35f,r.top+r.height()*.20f,26,p);c.drawCircle(r.left+r.width()*.634f,r.top+r.height()*.554f,30,p);p.setStyle(Paint.Style.FILL);glass(c,670,160,585,463);text(c,UiText.get("guide.direct_exit"),695,202,30,true,0xffffdb4d);text(c,UiText.get("guide.hold"),695,244,23,false,Color.WHITE);text(c,UiText.get("guide.press_f"),695,280,22,false,Color.WHITE);text(c,UiText.get("guide.wait_menu"),695,316,23,false,Color.WHITE);text(c,UiText.get("guide.quick_menu"),695,375,29,true,0xff66e2c0);text(c,UiText.get("guide.quick_combo"),695,415,23,false,Color.WHITE);text(c,UiText.get("guide.quick_actions"),695,450,22,false,Color.WHITE);text(c,UiText.get("guide.in_game"),695,513,29,true,0xff66e2c0);text(c,UiText.get("guide.game_buttons"),695,550,22,false,Color.WHITE);text(c,UiText.get("guide.credit_start"),695,586,22,false,Color.WHITE);glass(c,28,540,615,81);text(c,UiText.get("guide.f_alone"),45,573,23,false,Color.WHITE);text(c,UiText.get("guide.no_poweroff"),45,605,21,false,Color.WHITE);}
 c.restore();}
}
